import{_ as r,l as n,o as e,c as l,v as t,p as s,x as i,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"期望与线性性","description":"","frontmatter":{"title":"期望与线性性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/expectation-linearity.md","filePath":"cs/expectation-linearity.md","lastUpdated":1789023840000}'),c={name:"cs/expectation-linearity.md"};function _(m,a,E,b,A,u){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="期望与线性性" tabindex="-1">期望与线性性 <a class="header-anchor" href="#期望与线性性" aria-label="Permalink to &quot;期望与线性性&quot;">​</a></h1><div class="epigraph"><p>期望可拆成和，即使变量互相纠缠；指示变量把「计数有多少个」变成一排 $0/1$ 的期望相加。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications；Shannon, 1948 整理</footer></div><p>上一课<a href="/cs/discrete-probability">离散概率够用的那一层</a>已经写下 \\(\\mathbb{E}[X+Y]=\\mathbb{E}[X]+\\mathbb{E}[Y]\\) 无需独立，并把熵当成 \\(-\\log p\\) 的期望。本课不重定义 \\(p_\\omega\\)，也不从测度论另起。缺口是：线性性还只是一句公理。后课哈希碰撞数、随机算法比较次数，要把「有多少对出事」写成和，必须会造<strong>指示变量</strong>，并忍住去假设独立。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(X\\) 是碰撞对数、环的个数、成功探测次数时，直接对 \\(X\\) 的分布求和往往难。缺口因此不是再讲 \\(\\sum p\\)，而是 \\(X=\\sum_i X_i\\)，其中 \\(X_i\\in\\{0,1\\}\\) 表示事件 \\(A_i\\) 是否发生，则 \\(\\mathbb{E}[X]=\\sum_i P(A_i)\\)，无论 \\(A_i\\) 如何相关。独立只在要把方差、或要把 \\(P(A\\cap B)\\) 收成乘积时才需要；本课不算方差。</p><p><a href="/cs/pigeonhole">鸽笼</a>给最坏存在碰撞；本课给期望个数。两者都不是「高概率」的 Chernoff——那不进主干。</p><h3 id="期望不是众数" tabindex="-1">期望不是众数 <a class="header-anchor" href="#期望不是众数" aria-label="Permalink to &quot;期望不是众数&quot;">​</a></h3><p>\\(\\mathbb{E}[X]\\) 可以不是支撑上的点，也可以远小于「几乎必然」的上界。把期望链长当成最大链长，后课哈希最坏情况会消失。</p><p><span class="marginnote">Rosen 用指示变量数有多少个固定点、多少对同生日。Shannon 的 \\(H(X)=\\mathbb{E}[-\\log p(X)]\\) 现在是线性性的实例：\\(-\\log p\\) 不必拆成独立和。下一课才把条件期望与贝叶斯当计算工具展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>确定指标集（点、边、无序对）。令 \\(X_i=\\mathbf{1}_{A_i}\\)。计算单个 \\(P(A_i)\\)——常常比 \\(X\\) 的整分布容易，再用线性性。例子： \\(n\\) 个球 \\(m\\) 个箱，期望非空箱数、期望碰撞对数。本课只写到 \\(\\mathbb{E}\\)，不把分布写成泊松。</p>',11)),(e(),s(d,null,{default:i(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%9C%89%E9%99%90%20p%22%5D%20--%3E%20IND%5B%22%E6%8C%87%E7%A4%BA%E5%8F%98%E9%87%8F%22%5D%0A%20%20IND%20--%3E%20LIN%5B%22E%20%E6%B1%82%E5%92%8C%E6%97%A0%E9%9C%80%E7%8B%AC%E7%AB%8B%22%5D%0A%20%20LIN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%9D%A1%E4%BB%B6%E4%B8%8E%E5%8F%8D%E8%BD%AC%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课快排期望比较次数、Bloom 的期望误阳，都是指示变量套线性性。熵已经是期望，无需本课再推；本课补的是「计数型」随机变量。器件噪声仍不是本课对象。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入方差、协方差、大数定律证明。连续期望不进本栏。条件期望 \\(\\mathbb{E}[X|Y]\\) 与贝叶斯公式下一课才钉成计算步骤；上一课的 \\(P(A|B)\\) 定义在此够引用，不够当方法。</p><p>后课默认：要期望个数，拆指示变量再相加；独立另说。反转 \\(P(\\text{因}|\\text{果})\\) 是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线性性对相关变量也成立；指示变量把计数变成概率和。</li><li>期望个数不是最坏存在，也不是高概率界。</li><li>条件概率的反转与全期望展开留给下一课。</li><li>出处：Rosen；Shannon, 1948。</li></ul>',7))])}const x=r(c,[["render",_]]);export{B as __pageData,x as default};
